(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const pages=window.LF_CC_PAGES||[], maps=window.LF_CC_MAPS||[];
let D={},relationshipLimit=36;
const api=async(u,o={})=>{const r=await fetch(u,o);if(r.status===401){location.href='/admin/login';throw Error('Login required')}const ct=r.headers.get('content-type')||'',b=ct.includes('json')?await r.json():await r.text();if(!r.ok)throw Error(b?.detail||b||r.statusText);return b};
const post=(u,b)=>api(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),put=(u,b)=>api(u,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),del=u=>api(u,{method:'DELETE'});
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const toast=(m,t='')=>{const e=document.createElement('div');e.className='toast '+t;e.textContent=m;$('#toastStack')?.appendChild(e);setTimeout(()=>e.remove(),3300)};
const modal=(html,ready)=>{const el=$('#ccModal');$('#ccModalContent').innerHTML=html;el.classList.remove('hidden');$('[data-close-cc-modal]').onclick=()=>el.classList.add('hidden');ready?.()};
const closeModal=()=>$('#ccModal').classList.add('hidden');
const pageOptions=(value='',none='None')=>`<option value="">${esc(none)}</option>`+pages.map(p=>`<option value="${esc(p.slug)}" ${p.slug===value?'selected':''}>${esc((p.chapter&&p.chapter!==p.title?p.chapter+' · ':'')+p.title)}</option>`).join('');
const inviteOptions=(selected=[])=>{const set=new Set((selected||[]).map(Number));return (D.invitations||[]).filter(x=>x.is_active!==false).map(i=>`<label class="audience-chip"><input type="checkbox" value="${i.id}" ${set.has(Number(i.id))?'checked':''}><span>${esc(i.label||('Player '+i.id))}</span></label>`).join('')||'<span class="empty-mini">No invitations yet.</span>'};
function tab(name){$$('[data-cc-tab]').forEach(x=>x.classList.toggle('active',x.dataset.ccTab===name));$$('.cc-pane').forEach(x=>x.classList.toggle('active',x.id==='cc-'+name));history.replaceState(null,'','#'+name)}
$$('[data-cc-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.ccTab));$$('[data-jump]').forEach(b=>b.onclick=()=>tab(b.dataset.jump));if(location.hash&&$('#cc-'+location.hash.slice(1)))tab(location.hash.slice(1));
async function load(){D=await api('/api/admin/campaign/overview');renderAll()}
function renderAll(){renderDashboard();renderCampaigns();renderSessions();renderParty();renderTimeline();renderRelationships();renderReveals();renderMysteries();renderHandouts();renderWorld();renderAtlas();renderHealth();renderSnapshots()}

function renderCampaigns(){
  const rows=D.campaigns||[],host=$('#ccCampaignList');if(!host)return;
  host.innerHTML=rows.map(c=>`<article class="cc-item-card campaign-card ${c.id===D.active_campaign?.id?'active-campaign':''}" style="--campaign-accent:${esc(c.accent||'#b79661')}"><span class="cc-status status-${esc(c.status)}">${c.id===D.active_campaign?.id?'ACTIVE TABLE':esc(c.status)}</span><small>${c.is_default?'DEFAULT · ':''}${c.member_count||c.member_ids?.length||0} PLAYERS</small><h2>${esc(c.name)}</h2><p>${esc(c.description||'A campaign in this setting.')}</p><div><a href="/schedule" data-plan-campaign="${c.id}">Planner</a><button data-switch-campaign="${c.id}">${c.id===D.active_campaign?.id?'Current':'Switch here'}</button>${window.SEEKER_OWNER?`<button data-edit-campaign="${c.id}">Edit</button>${c.is_default?'':`<button data-default-campaign="${c.id}">Make default</button>`}${c.is_default?'':`${c.status==='archived'?'':`<button data-archive-campaign="${c.id}">Archive</button>`}<button class="danger-text" data-delete-campaign="${c.id}">Delete</button>`}`:''}</div></article>`).join('')||'<div class="timeline-empty"><h2>No campaigns found.</h2></div>';
  $$('[data-switch-campaign]').forEach(b=>b.onclick=async()=>{if(+b.dataset.switchCampaign===+D.active_campaign?.id)return;await post('/api/campaign/select',{campaign_id:+b.dataset.switchCampaign});location.reload()});
  $$('[data-plan-campaign]').forEach(a=>a.onclick=async e=>{e.preventDefault();const cid=+a.dataset.planCampaign;if(cid!==+D.active_campaign?.id)await post('/api/campaign/select',{campaign_id:cid});location.href='/schedule'});
  $$('[data-edit-campaign]').forEach(b=>b.onclick=()=>campaignModal(rows.find(x=>x.id===+b.dataset.editCampaign)));
  $$('[data-default-campaign]').forEach(b=>b.onclick=async()=>{await post('/api/admin/campaigns/'+b.dataset.defaultCampaign+'/default',{});await load();toast('Default campaign changed')});
  $$('[data-archive-campaign]').forEach(b=>b.onclick=async()=>{if(!confirm('Archive this campaign? Players will no longer be able to switch into it, but all records are preserved.'))return;await post('/api/admin/campaigns/'+b.dataset.archiveCampaign+'/archive',{});await load();toast('Campaign archived')});
  $$('[data-delete-campaign]').forEach(b=>b.onclick=async()=>{const c=rows.find(x=>x.id===+b.dataset.deleteCampaign);if(!c||c.is_default)return;const msg=`Permanently delete “${c.name}”?\n\nThis removes this table's characters, sessions, notes, mysteries, reveals, objectives, prep and other campaign-specific records. Shared setting canon and each player's global availability are kept.\n\nThis cannot be undone.`;if(!confirm(msg))return;await del('/api/admin/campaigns/'+b.dataset.deleteCampaign);toast('Campaign deleted');location.reload()});
}
function campaignModal(c={}){const selected=new Set((c.member_ids||[]).map(Number));modal(`<h2>${c.id?'Edit':'New'} campaign</h2><label>Name<input id="fCampaignName" value="${esc(c.name||'')}"></label><label>Description<textarea id="fCampaignDescription" placeholder="Which party and story belongs here?">${esc(c.description||'')}</textarea></label><div class="form-grid"><label>Accent<input id="fCampaignAccent" type="color" value="${esc(c.accent||'#b79661')}"></label><label>Status<select id="fCampaignStatus"><option value="active">Active</option><option value="archived" ${c.status==='archived'?'selected':''}>Archived</option></select></label></div><label>Players in this campaign</label><div class="audience-grid" id="fCampaignMembers">${(D.invitations||[]).filter(i=>i.is_active!==false).map(i=>`<label class="audience-chip"><input type="checkbox" value="${i.id}" ${selected.has(+i.id)?'checked':''}><span>${esc(i.label)}</span></label>`).join('')||'<span class="empty-mini">Create player invitations first.</span>'}</div><p class="storage-help">These checkboxes grant table access in advance. Players also join an active campaign automatically when they assign one of their own characters to it. Their notes and spoilers remain campaign-specific.</p><div class="modal-actions"><button id="saveCampaignModal" class="compile-btn">Save campaign</button></div>`,()=>{$('#saveCampaignModal').onclick=async()=>{const member_ids=$$('#fCampaignMembers input:checked').map(x=>+x.value);await post('/api/admin/campaigns',{...c,name:$('#fCampaignName').value,description:$('#fCampaignDescription').value,accent:$('#fCampaignAccent').value,status:$('#fCampaignStatus').value,member_ids});closeModal();await load();toast('Campaign saved')}})}
if($('#ccNewCampaign'))$('#ccNewCampaign').onclick=()=>campaignModal({status:'active',accent:'#b79661',member_ids:[]});
$$('[data-campaign-select]').forEach(select=>select.onchange=async()=>{if(select.value==='__all__'){location.href='/tables';return}select.disabled=true;try{await post('/api/campaign/select',{campaign_id:+select.value});location.reload()}catch(e){select.disabled=false;toast(e.message,'error')}});

function renderDashboard(){const h=D.health||{counts:{}};$('#ccDashboardStats').innerHTML=[['Codex entries',h.counts?.pages||pages.length],['Relationships',h.counts?.relationships||0],['Open mysteries',(D.mysteries||[]).filter(x=>x.status==='open').length],['Health findings',h.counts?.issues||0]].map(([a,b])=>`<div class="cc-stat"><strong>${esc(b)}</strong><span>${esc(a)}</span></div>`).join('');const live=(D.sessions||[]).find(x=>x.status==='live');$('#ccLiveSession').innerHTML=live?`<div class="cc-live-card"><span>● LIVE</span><strong>${esc((live.session_number?'Session '+live.session_number+' · ':'')+live.title)}</strong><p>${esc(live.summary||'')}</p><a href="/gm/session">Run session →</a></div>`:'<div class="empty-mini">No session is live. <a href="/gm/session">Open Session Console →</a></div>';$('#ccHealthSummary').innerHTML=`<strong>${h.counts?.issues||0} findings</strong><p>${h.counts?.orphans||0} orphan entries · ${h.counts?.unvisited||0} never opened by players</p>`;$('#ccRecentUpdates').innerHTML=(D.recent_updates||[]).slice(0,5).map(u=>`<article><strong>${esc(u.title)}</strong><small>${esc(u.body)}</small></article>`).join('')||'<div class="empty-mini">No player-facing discoveries yet.</div>';$('#ccQuickDate').value=D.calendar?.current_date||''}
function renderParty(){const rows=D.player_characters||[],host=$('#ccPartyList');if(!host)return;host.innerHTML=rows.map(c=>`<article class="cc-item-card party-card" style="--party-accent:${esc(c.theme_color||'#b79661')}">${c.portrait_url?`<div class="party-card-portrait" style="background-image:url('${esc(c.portrait_url)}')"></div>`:'<div class="party-card-portrait placeholder">♟</div>'}<small>${esc(c.player_label||'Player')} · ${esc(c.status||'active').toUpperCase()}</small><h2>${esc(c.name)}</h2><p>${esc([c.ancestry,c.class_name,c.level!=null?'Level '+c.level:''].filter(Boolean).join(' · '))}</p><div><a href="/characters/${c.id}">Open dossier</a></div></article>`).join('')||'<div class="timeline-empty"><h2>No player characters yet.</h2><p>Players can create their own characters from the Player Characters screen.</p><a class="quiet-btn" href="/characters">Open character shelf</a></div>'}
function renderSessions(){const rows=D.sessions||[];$('#ccSessionList').innerHTML=rows.length?rows.slice().reverse().map(s=>`<article class="cc-item-card"><span class="cc-status status-${esc(s.status)}">${esc(s.status)}</span><small>${s.session_number?'SESSION '+s.session_number:'SESSION'} ${esc(s.session_date||'')}</small><h2>${esc(s.title)}</h2><p>${esc(s.summary||'No player-facing recap yet.')}</p><div><button data-edit-session="${s.id}">Edit</button>${s.status!=='live'?`<button data-live-session="${s.id}">Go live</button>`:''}<a href="/session">Player ↗</a><button data-delete-session="${s.id}" class="danger-text">Delete</button></div></article>`).join(''):'<div class="timeline-empty"><h2>No sessions yet.</h2></div>';$$('[data-edit-session]').forEach(b=>b.onclick=()=>sessionModal(rows.find(x=>x.id===+b.dataset.editSession)));$$('[data-live-session]').forEach(b=>b.onclick=async()=>{const s=rows.find(x=>x.id===+b.dataset.liveSession);await post('/api/admin/sessions',{...s,status:'live'});await load();toast('Session is live')});$$('[data-delete-session]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this session record?')){await del('/api/admin/sessions/'+b.dataset.deleteSession);await load()}})}
function sessionModal(s={}){modal(`<h2>${s.id?'Edit':'New'} session</h2><div class="form-grid"><label>Number<input id="fSessionNo" type="number" value="${esc(s.session_number||'')}"></label><label>Date<input id="fSessionDate" value="${esc(s.session_date||'')}"></label></div><label>Title<input id="fSessionTitle" value="${esc(s.title||'')}"></label><label>Status<select id="fSessionStatus"><option value="planned">Planned</option><option value="live" ${s.status==='live'?'selected':''}>Live</option><option value="ended" ${s.status==='ended'?'selected':''}>Ended</option></select></label><label>Player recap / session journal<textarea id="fSessionSummary">${esc(s.summary||'')}</textarea></label><label>Private GM notes<textarea id="fSessionGM">${esc(s.gm_notes||'')}</textarea></label><label>Current location<select id="fSessionLocation">${pageOptions(s.current_location_slug||'')}</select></label><label>Spotlight map<select id="fSessionMap"><option value="">None</option>${maps.map(m=>`<option value="${esc(m.slug)}" ${m.slug===s.spotlight_map_slug?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><div class="modal-actions"><button class="compile-btn" id="saveSessionModal">Save session</button></div>`,()=>{$('#saveSessionModal').onclick=async()=>{await post('/api/admin/sessions',{...s,session_number:+$('#fSessionNo').value||null,session_date:$('#fSessionDate').value,title:$('#fSessionTitle').value||'Session',status:$('#fSessionStatus').value,summary:$('#fSessionSummary').value,gm_notes:$('#fSessionGM').value,current_location_slug:$('#fSessionLocation').value||null,spotlight_map_slug:$('#fSessionMap').value||null});closeModal();await load();toast('Session saved')}})}
$('#ccNewSession').onclick=()=>sessionModal({status:'planned'});
const HIST_KINDS=[['event','Turning point'],['founding','Founding'],['war','War'],['reign','Reign / rule'],['catastrophe','Catastrophe'],['treaty','Treaty'],['discovery','Discovery'],['migration','Migration'],['revolution','Revolution'],['journey','Journey'],['birth','Birth'],['death','Death']];
function historySortKey(label){const t=String(label||'').trim();const m=t.match(/-?\d+(?:\.\d+)?/);if(!m)return 0;let n=+m[0];if(/\b(?:bc|bce|before)\b/i.test(t)&&n>0)n=-n;return n}
function renderTimeline(){const eras=D.timeline_eras||[],events=D.timeline||[],host=$('#ccEraList'),un=$('#ccTimelineUnplaced');if(!host||!un)return;host.innerHTML=eras.map(era=>{const ev=events.filter(e=>+e.era_id===+era.id);return `<article class="history-era-card" style="--era-accent:${esc(era.accent||'#b79661')}"><header><div><small>${esc([era.start_label,era.end_label].filter(Boolean).join(' — ')||'ERA')}</small><h2>${esc(era.name)}</h2><p>${esc(era.summary||'')}</p></div><div><button data-add-era-event="${era.id}">＋ Event</button><button data-edit-era="${era.id}">Edit era</button><button data-del-era="${era.id}" class="danger-text">×</button></div></header><div class="history-event-stack">${ev.map(historyEventRow).join('')||'<div class="empty-mini">No events placed in this era yet.</div>'}</div></article>`}).join('')||'<div class="history-zero"><span>⌛</span><h2>Start with an era</h2><p>Give history a few big shelves before adding hundreds of individual dates.</p><button class="compile-btn" id="historyZeroEra">＋ Create first era</button></div>';const loose=events.filter(e=>!e.era_id);un.innerHTML=loose.map(historyEventRow).join('')||'<div class="empty-mini">Everything is placed in an era.</div>';$$('[data-edit-event]').forEach(b=>b.onclick=()=>timelineModal(events.find(x=>x.id===+b.dataset.editEvent)));$$('[data-del-event]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this historical record?')){await del('/api/admin/timeline/'+b.dataset.delEvent);await load()}});$$('[data-edit-era]').forEach(b=>b.onclick=()=>eraModal(eras.find(x=>x.id===+b.dataset.editEra)));$$('[data-add-era-event]').forEach(b=>b.onclick=()=>timelineModal({era_id:+b.dataset.addEraEvent,kind:'event',visibility:'players',significance:2}));$$('[data-del-era]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this era? Its events will become unplaced, not deleted.')){await del('/api/admin/timeline-eras/'+b.dataset.delEra);await load()}});$('#historyZeroEra')&&($('#historyZeroEra').onclick=()=>eraModal({visibility:'players'}))}
function historyEventRow(e){const stars='◆'.repeat(Math.max(1,Math.min(5,+e.significance||2)));return `<div class="history-event-row"><span class="history-date">${esc(e.date_label||'Undated')}${e.end_date_label?`<small>→ ${esc(e.end_date_label)}</small>`:''}</span><span class="history-kind kind-${esc(e.kind)}">${esc((HIST_KINDS.find(x=>x[0]===e.kind)||[0,e.kind])[1])}</span><div><strong>${esc(e.title)}</strong><p>${esc(e.body||'')}</p><small>${stars} · ${esc(e.certainty||'recorded')}</small></div><button data-edit-event="${e.id}">Edit</button><button data-del-event="${e.id}" class="danger-text">×</button></div>`}
function eraModal(e={}){modal(`<h2>${e.id?'Edit':'Create'} historical era</h2><p class="storage-help">Eras are the large shelves of your world's history. Events can then be dropped into them.</p><label>Era name<input id="fEraName" value="${esc(e.name||'') }" placeholder="Age of the Sky Triune"></label><div class="form-grid"><label>Begins <input id="fEraStart" value="${esc(e.start_label||'')}" placeholder="0 p.C."></label><label>Ends <input id="fEraEnd" value="${esc(e.end_label||'')}" placeholder="312 p.C."></label></div><label>One-sentence historical identity<textarea id="fEraSummary" rows="4">${esc(e.summary||'')}</textarea></label><div class="form-grid"><label>Accent<input id="fEraAccent" type="color" value="${esc(e.accent||'#b79661')}"></label><label>Visibility<select id="fEraVisibility"><option value="players">Players</option><option value="gm" ${e.visibility==='gm'?'selected':''}>GM only</option></select></label></div><div class="modal-actions"><button id="saveEraModal" class="compile-btn">Save era</button></div>`,()=>{$('#saveEraModal').onclick=async()=>{const start=$('#fEraStart').value,end=$('#fEraEnd').value;await post('/api/admin/timeline-eras',{...e,name:$('#fEraName').value||'Unnamed era',start_label:start,end_label:end,start_sort:historySortKey(start),end_sort:historySortKey(end),summary:$('#fEraSummary').value,accent:$('#fEraAccent').value,visibility:$('#fEraVisibility').value});closeModal();await load();toast('Historical era saved')}})}
function timelineModal(e={}){const eraOpts='<option value="">Unplaced</option>'+(D.timeline_eras||[]).map(x=>`<option value="${x.id}" ${+e.era_id===+x.id?'selected':''}>${esc(x.name)}</option>`).join('');modal(`<h2>${e.id?'Edit':'Add'} historical record</h2><div class="history-kind-picker">${HIST_KINDS.map(([k,l])=>`<button type="button" data-history-kind="${k}" class="${(e.kind||'event')===k?'active':''}">${esc(l)}</button>`).join('')}</div><input id="fEventKind" type="hidden" value="${esc(e.kind||'event')}"><label>What happened?<input id="fEventTitle" value="${esc(e.title||'')}" placeholder="The Shattering of the Lord in Iron"></label><div class="form-grid"><label>Date / year<input id="fEventDate" value="${esc(e.date_label||'')}" placeholder="423 p.C."></label><label>End date <small>optional for reigns, wars, ages</small><input id="fEventEnd" value="${esc(e.end_date_label||'')}"></label></div><label>Era<select id="fEventEra">${eraOpts}</select></label><label>What changed because of it?<textarea id="fEventBody" rows="6">${esc(e.body||'')}</textarea></label><label>Related Codex entry<select id="fEventPage">${pageOptions(e.page_slug||'')}</select></label><div class="form-grid"><label>Importance<select id="fEventSignificance">${[1,2,3,4,5].map(n=>`<option value="${n}" ${+(e.significance||2)===n?'selected':''}>${'◆'.repeat(n)} ${['Minor','Notable','Major','Era-defining','Foundational'][n-1]}</option>`).join('')}</select></label><label>Historical certainty<select id="fEventCertainty"><option value="recorded" ${e.certainty==='recorded'?'selected':''}>Recorded history</option><option value="legend" ${e.certainty==='legend'?'selected':''}>Legend / disputed</option><option value="myth" ${e.certainty==='myth'?'selected':''}>Mythic age</option><option value="secret" ${e.certainty==='secret'?'selected':''}>Hidden truth</option></select></label></div><label>Visibility<select id="fEventVisibility"><option value="players">Players</option><option value="gm" ${e.visibility==='gm'?'selected':''}>GM only</option></select></label><details class="history-advanced"><summary>Advanced ordering</summary><div class="form-grid"><label>Start sort key<input id="fEventSort" type="number" step="0.01" value="${esc(e.sort_key??'')}"></label><label>End sort key<input id="fEventEndSort" type="number" step="0.01" value="${esc(e.end_sort_key??'')}"></label></div></details><div class="modal-actions"><button class="compile-btn" id="saveEventModal">Save historical record</button></div>`,()=>{$$('.history-kind-picker button').forEach(b=>b.onclick=()=>{$$('.history-kind-picker button').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#fEventKind').value=b.dataset.historyKind});$('#saveEventModal').onclick=async()=>{const d=$('#fEventDate').value,ed=$('#fEventEnd').value;await post('/api/admin/timeline',{...e,title:$('#fEventTitle').value,date_label:d,sort_key:$('#fEventSort').value!==''?+$('#fEventSort').value:historySortKey(d),end_date_label:ed,end_sort_key:$('#fEventEndSort').value!==''?+$('#fEventEndSort').value:(ed?historySortKey(ed):null),kind:$('#fEventKind').value,era_id:+$('#fEventEra').value||null,page_slug:$('#fEventPage').value||null,body:$('#fEventBody').value,significance:+$('#fEventSignificance').value||2,certainty:$('#fEventCertainty').value,visibility:$('#fEventVisibility').value});closeModal();await load();toast('History updated')}})}
$('#ccNewTimeline').onclick=()=>timelineModal({kind:'event',visibility:'players',significance:2});$('#ccNewEra').onclick=()=>eraModal({visibility:'players'});
function renderRelationships(){
  const all=D.relationships||[],q=($('#ccRelationshipSearch')?.value||'').trim().toLowerCase(),kind=$('#ccRelationshipFilter')?.value||'';
  const types=[...new Set(all.map(r=>r.relation).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const filter=$('#ccRelationshipFilter');if(filter){const keep=filter.value;filter.innerHTML='<option value="">All relationship types</option>'+types.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');filter.value=types.includes(keep)?keep:''}
  const title=slug=>pages.find(p=>p.slug===slug)?.title||slug;
  const rels=all.filter(r=>{if(kind&&r.relation!==kind)return false;if(!q)return true;return [r.relation,r.label,title(r.source_slug),title(r.target_slug),r.source_slug,r.target_slug].some(v=>String(v||'').toLowerCase().includes(q))});
  const shown=rels.slice(0,relationshipLimit),host=$('#ccRelationshipList');
  if(host)host.innerHTML=shown.map(r=>`<div class="cc-list-row relation compact-relation"><div><small>${esc(r.relation)}</small><strong>${esc(title(r.source_slug))} <span aria-hidden="true">→</span> ${esc(title(r.target_slug))}</strong>${r.label?`<p>${esc(r.label)}</p>`:''}</div><div class="relationship-row-actions"><button type="button" data-edit-rel="${r.id}">Edit</button><button type="button" data-del-rel="${r.id}" class="danger-text" aria-label="Delete relationship">×</button></div></div>`).join('')||'<div class="empty-mini">No relationships match this view.</div>';
  const count=$('#ccRelationshipCount');if(count)count.textContent=`${rels.length} connection${rels.length===1?'':'s'}`;
  const more=$('#ccRelationshipMore');if(more){more.classList.toggle('hidden',shown.length>=rels.length);more.textContent=`Show ${Math.min(36,rels.length-shown.length)} more`}
  $$('[data-edit-rel]').forEach(b=>b.onclick=()=>relationshipModal(all.find(x=>x.id===+b.dataset.editRel)));
  $$('[data-del-rel]').forEach(b=>b.onclick=async()=>{if(confirm('Delete relationship?')){await del('/api/admin/relationships/'+b.dataset.delRel);await load()}});
  $('#ccAliasPage').innerHTML=pageOptions();$('#ccAliasList').innerHTML=Object.entries(D.aliases||{}).map(([a,s])=>`<span>${esc(a)} → ${esc(title(s))}</span>`).join('');const ep=$('#ccEntityPage');const current=ep.value;ep.innerHTML=pageOptions(current,'Choose entry');if(current)ep.value=current;renderEntityForm()
}
function relationshipModal(r={}){
  const presets=['ally of','enemy of','member of','leader of','serves','worships','located in','rules','founded by','parent of','child of','sibling of','mentor of','rival of','created','owns','protects','betrayed'];
  modal(`<h2>${r.id?'Edit':'Connect'} lore</h2><p class="storage-help">Search for each entry instead of scrolling through the whole Codex.</p><div class="relationship-search-pair"><div><label>Source<input id="fRelSourceSearch" autocomplete="off" placeholder="Search source…"></label><input id="fRelSource" type="hidden" value="${esc(r.source_slug||'')}"><div id="fRelSourcePicked" class="relationship-picked"></div><div id="fRelSourceResults" class="relationship-picker-results"></div></div><div><label>Target<input id="fRelTargetSearch" autocomplete="off" placeholder="Search target…"></label><input id="fRelTarget" type="hidden" value="${esc(r.target_slug||'')}"><div id="fRelTargetPicked" class="relationship-picked"></div><div id="fRelTargetResults" class="relationship-picker-results"></div></div></div><label>Relationship<select id="fRelType">${presets.map(x=>`<option ${r.relation===x?'selected':''}>${x}</option>`).join('')}<option value="custom" ${r.relation&&!presets.includes(r.relation)?'selected':''}>custom…</option></select></label><label id="fRelCustomWrap" class="${r.relation&&!presets.includes(r.relation)?'':'hidden'}">Custom relationship<input id="fRelCustom" value="${esc(r.relation&&!presets.includes(r.relation)?r.relation:'')}"></label><div class="relationship-preview" id="fRelPreview"></div><label>Optional display note<input id="fRelLabel" value="${esc(r.label||'')}" placeholder="Financial architect of the revolution"></label><label>Visibility<select id="fRelVisibility"><option value="players">Players</option><option value="gm" ${r.visibility==='gm'?'selected':''}>GM only</option></select></label><div class="modal-actions"><button type="button" id="saveRelModal" class="compile-btn">Save connection</button></div>`,()=>{
    const preview=()=>{const a=pages.find(p=>p.slug===$('#fRelSource').value)?.title||'Source',b=pages.find(p=>p.slug===$('#fRelTarget').value)?.title||'Target',kind=$('#fRelType').value==='custom'?($('#fRelCustom').value||'related to'):$('#fRelType').value;$('#fRelCustomWrap').classList.toggle('hidden',$('#fRelType').value!=='custom');$('#fRelPreview').textContent=`${a}  ${kind}  ${b}`};
    const setup=(side,current)=>{
      const search=$(`#fRel${side}Search`),hidden=$(`#fRel${side}`),picked=$(`#fRel${side}Picked`),results=$(`#fRel${side}Results`);
      const choose=p=>{if(!p)return;hidden.value=p.slug;picked.innerHTML=`<span>Selected</span><strong>${esc(p.title)}</strong><small>${esc(p.chapter||'Codex')}</small>`;results.innerHTML='';preview()};
      const render=()=>{const q=(search.value||'').trim().toLowerCase(),found=pages.filter(p=>!q||(p.title||'').toLowerCase().includes(q)||(p.chapter||'').toLowerCase().includes(q)||(p.slug||'').includes(q)).slice(0,10);results.innerHTML=found.map(p=>`<button type="button" data-pick-rel="${esc(p.slug)}"><strong>${esc(p.title)}</strong><small>${esc(p.chapter||'Codex')}</small></button>`).join('')||'<p>No matching Codex entry.</p>';results.querySelectorAll('[data-pick-rel]').forEach(b=>{b.onclick=()=>choose(pages.find(p=>p.slug===b.dataset.pickRel))})};
      search.oninput=render;search.onfocus=render;const initial=pages.find(p=>p.slug===current);if(initial)choose(initial)
    };
    setup('Source',r.source_slug);setup('Target',r.target_slug);['fRelType','fRelCustom'].forEach(id=>$('#'+id)?.addEventListener('input',preview));preview();
    $('#saveRelModal').onclick=async()=>{const source=$('#fRelSource').value,target=$('#fRelTarget').value;if(!source||!target)return toast('Choose both a source and a target','error');if(source===target)return toast('A relationship needs two different entries','error');const relation=$('#fRelType').value==='custom'?$('#fRelCustom').value.trim():$('#fRelType').value;if(!relation)return toast('Describe the relationship','error');try{await post('/api/admin/relationships',{...r,source_slug:source,target_slug:target,relation,label:$('#fRelLabel').value,visibility:$('#fRelVisibility').value});closeModal();await load();toast('Relationship saved')}catch(e){toast(e.message,'error')}};
  })
}
$('#ccRelationshipSearch')?.addEventListener('input',()=>{relationshipLimit=36;renderRelationships()});$('#ccRelationshipFilter')?.addEventListener('change',()=>{relationshipLimit=36;renderRelationships()});$('#ccRelationshipMore')?.addEventListener('click',()=>{relationshipLimit+=36;renderRelationships()});document.addEventListener('click',e=>{const b=e.target.closest?.('#ccNewRelationship');if(!b)return;e.preventDefault();relationshipModal({visibility:'players'})});$('#ccSaveAlias').onclick=async()=>{if(!$('#ccAliasName').value.trim()||!$('#ccAliasPage').value)return toast('Choose an alias and destination','error');await post('/api/admin/aliases',{alias:$('#ccAliasName').value.trim(),page_slug:$('#ccAliasPage').value});$('#ccAliasName').value='';await load();toast('Alias saved')};
function renderEntityForm(){const slug=$('#ccEntityPage')?.value||'';const styles=D.entity_styles||{};const s=styles[slug]||{};$('#ccEntityType').value=s.dossier_type||'auto';$('#ccEntityAccent').value=/^#[0-9a-f]{6}$/i.test(s.accent||'')?s.accent:'#b79661';$('#ccEntityMotif').value=s.motif||'';const imageAssets=D.assets||[];$('#ccEntityCrest').innerHTML='<option value="">None</option>'+imageAssets.map(a=>`<option value="${esc(a.ref||a.path||'')}" ${(a.ref||a.path)===s.crest_ref?'selected':''}>${esc(a.name||a.path||a.ref)}</option>`).join('');const media=D.media_assets||[];$('#ccEntityAudio').innerHTML='<option value="">None</option>'+media.map(a=>`<option value="${esc(a.ref||a.path||'')}" ${(a.ref||a.path)===s.ambient_audio_ref?'selected':''}>${esc(a.name||a.path||a.ref)}</option>`).join('')}
$('#ccEntityPage').onchange=renderEntityForm;$('#ccSaveEntityStyle').onclick=async()=>{const slug=$('#ccEntityPage').value;if(!slug)return toast('Choose a Codex entry','error');const s=await put('/api/admin/entity-style/'+encodeURIComponent(slug),{dossier_type:$('#ccEntityType').value,accent:$('#ccEntityAccent').value,motif:$('#ccEntityMotif').value,crest_ref:$('#ccEntityCrest').value,ambient_audio_ref:$('#ccEntityAudio').value});D.entity_styles=D.entity_styles||{};D.entity_styles[slug]=s;toast('Dossier identity saved')};
function renderReveals(){const states=new Map((D.reveal_states||[]).map(x=>[x.target_key,x]));$('#ccRevealList').innerHTML=(D.reveals||[]).map(r=>{const row=states.get(r.target_key)||{},st=row.state||'hidden',aud=row.audience||[];return `<div class="cc-list-row reveal"><div><small>${esc(r.page_title)}</small><strong>${esc(r.key)}</strong><p>${esc(row.rumor_text||r.rumor||'No rumor text.')}</p>${aud.length?`<em>${aud.length} player-specific</em>`:''}</div><select data-reveal-state="${esc(r.target_key)}"><option value="hidden" ${st==='hidden'?'selected':''}>Hidden</option><option value="rumor" ${st==='rumor'?'selected':''}>Rumor</option><option value="discovered" ${st==='discovered'?'selected':''}>Discovered</option><option value="public" ${st==='public'?'selected':''}>Public</option></select><button data-advanced-reveal="${esc(r.target_key)}">Audience</button></div>`}).join('')||'<div class="empty-mini">No progressive-lore blocks found. Add seeker-reveal comments in your LaTeX source.</div>';$$('[data-reveal-state]').forEach(sel=>sel.onchange=async()=>{const r=D.reveals.find(x=>x.target_key===sel.dataset.revealState),row=states.get(r.target_key)||{};await post('/api/admin/reveals',{target_type:'block',target_key:r.target_key,state:sel.value,rumor_text:row.rumor_text||r.rumor,title:r.page_title+' · '+r.key,audience:row.audience||[],expires_at:row.expires_at||null});await load();toast('Reveal state changed')});$$('[data-advanced-reveal]').forEach(b=>b.onclick=()=>revealModal(D.reveals.find(x=>x.target_key===b.dataset.advancedReveal),states.get(b.dataset.advancedReveal)||{}));renderVariants()}
function revealModal(r,row={}){const exp=row.expires_at?new Date(row.expires_at*1000).toISOString().slice(0,16):'';modal(`<h2>Reveal audience</h2><p class="storage-help">${esc(r.page_title)} · ${esc(r.key)}</p><label>State<select id="fRevealState"><option value="hidden">Hidden</option><option value="rumor" ${row.state==='rumor'?'selected':''}>Rumor</option><option value="discovered" ${row.state==='discovered'?'selected':''}>Discovered</option><option value="public" ${row.state==='public'?'selected':''}>Public</option></select></label><label>Rumor text<textarea id="fRevealRumor">${esc(row.rumor_text||r.rumor||'')}</textarea></label><label>Temporary reveal expiry <small>leave blank for permanent</small><input id="fRevealExpires" type="datetime-local" value="${exp}"></label><fieldset><legend>Audience</legend><p class="storage-help">No players selected = whole party. Select individual invitations for private discoveries.</p><div class="audience-grid">${inviteOptions(row.audience||[])}</div></fieldset><div class="modal-actions"><button id="saveRevealModal" class="compile-btn">Save reveal</button></div>`,()=>{$('#fRevealState').value=row.state||'hidden';$('#saveRevealModal').onclick=async()=>{const audience=[...document.querySelectorAll('.audience-grid input:checked')].map(x=>+x.value);const dt=$('#fRevealExpires').value;await post('/api/admin/reveals',{target_type:'block',target_key:r.target_key,state:$('#fRevealState').value,rumor_text:$('#fRevealRumor').value,audience,expires_at:dt?new Date(dt).getTime()/1000:null,title:r.page_title+' · '+r.key});closeModal();await load();toast('Reveal rules saved')}})}
function renderVariants(){$('#ccVariantList').innerHTML=(D.variants||[]).map(v=>`<div class="cc-list-row variant"><div><small>${esc(pages.find(p=>p.slug===v.page_slug)?.title||v.page_slug)} · ${esc(v.state)}</small><strong>${esc(v.label||v.variant_key)}</strong><p>${esc((v.state==='truth'?v.truth_text:v.common_text)||'')}</p></div><button data-edit-variant="${v.id}">Edit</button><button data-del-variant="${v.id}" class="danger-text">×</button></div>`).join('')||'<div class="empty-mini">No unreliable-lore accounts yet.</div>';$$('[data-edit-variant]').forEach(b=>b.onclick=()=>variantModal((D.variants||[]).find(x=>x.id===+b.dataset.editVariant)));$$('[data-del-variant]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this account?')){await del('/api/admin/variants/'+b.dataset.delVariant);await load()}})}
function variantModal(v={}){modal(`<h2>${v.id?'Edit':'New'} unreliable account</h2><label>Codex entry<select id="fVariantPage">${pageOptions(v.page_slug||'','Choose entry')}</select></label><label>Label<input id="fVariantLabel" value="${esc(v.label||'Accounts differ')}"></label><label>Key<input id="fVariantKey" value="${esc(v.variant_key||'')}"></label><label>What people commonly believe<textarea id="fVariantCommon">${esc(v.common_text||'')}</textarea></label><label>Hidden truth<textarea id="fVariantTruth">${esc(v.truth_text||'')}</textarea></label><label>Players currently see<select id="fVariantState"><option value="common" ${v.state!=='truth'?'selected':''}>Common belief</option><option value="truth" ${v.state==='truth'?'selected':''}>Truth</option></select></label><label>Visibility<select id="fVariantVis"><option value="players">Players</option><option value="gm" ${v.visibility==='gm'?'selected':''}>GM only</option></select></label><div class="modal-actions"><button id="saveVariantModal" class="compile-btn">Save account</button></div>`,()=>{$('#saveVariantModal').onclick=async()=>{await post('/api/admin/variants',{...v,page_slug:$('#fVariantPage').value,label:$('#fVariantLabel').value,variant_key:$('#fVariantKey').value,common_text:$('#fVariantCommon').value,truth_text:$('#fVariantTruth').value,state:$('#fVariantState').value,visibility:$('#fVariantVis').value});closeModal();await load();toast('Lore account saved')}})}
$('#ccNewVariant').onclick=()=>variantModal({state:'common',visibility:'players'});
function renderMysteries(){$('#ccMysteryList').innerHTML=(D.mysteries||[]).map(m=>`<article class="cc-item-card"><span class="cc-status status-${esc(m.status)}">${esc(m.status)}</span><small>${m.pins?.length||0} CLUES · ${m.edges?.length||0} CONNECTIONS</small><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><div><button data-edit-mystery="${m.id}">Edit</button><button data-pin-mystery="${m.id}">＋ Clue</button><button data-connect-mystery="${m.id}" ${m.pins?.length<2?'disabled':''}>⌁ Connections</button><a href="/mysteries#${esc(m.slug)}">Player ↗</a><button data-del-mystery="${m.id}" class="danger-text">Delete</button></div></article>`).join('')||'<div class="empty-mini">No mystery boards yet.</div>';$$('[data-edit-mystery]').forEach(b=>b.onclick=()=>mysteryModal(D.mysteries.find(x=>x.id===+b.dataset.editMystery)));$$('[data-pin-mystery]').forEach(b=>b.onclick=()=>pinModal(+b.dataset.pinMystery));$$('[data-connect-mystery]').forEach(b=>b.onclick=()=>connectionsModal(D.mysteries.find(x=>x.id===+b.dataset.connectMystery)));$$('[data-del-mystery]').forEach(b=>b.onclick=async()=>{if(confirm('Delete mystery and its clues?')){await del('/api/admin/mysteries/'+b.dataset.delMystery);await load()}})}
function mysteryModal(m={}){modal(`<h2>${m.id?'Edit':'New'} mystery</h2><label>Title<input id="fMysteryTitle" value="${esc(m.title||'')}"></label><label>Description<textarea id="fMysteryBody">${esc(m.description||'')}</textarea></label><label>Status<select id="fMysteryStatus"><option value="open">Open</option><option value="solved" ${m.status==='solved'?'selected':''}>Solved</option><option value="dormant" ${m.status==='dormant'?'selected':''}>Dormant</option></select></label><label>Visibility<select id="fMysteryVis"><option value="players">Players</option><option value="gm" ${m.visibility==='gm'?'selected':''}>GM only</option></select></label><div class="modal-actions"><button id="saveMysteryModal" class="compile-btn">Save mystery</button></div>`,()=>{$('#saveMysteryModal').onclick=async()=>{await post('/api/admin/mysteries',{...m,title:$('#fMysteryTitle').value,description:$('#fMysteryBody').value,status:$('#fMysteryStatus').value,visibility:$('#fMysteryVis').value});closeModal();await load();toast('Mystery saved')}})}
function pinModal(mid){modal(`<h2>Pin a clue</h2><label>Label<input id="fPinLabel" placeholder="Broken sunstone shard"></label><label>Related Codex entry<select id="fPinPage">${pageOptions()}</select></label><label>Public note<textarea id="fPinNote"></textarea></label><div class="modal-actions"><button id="savePinModal" class="compile-btn">Pin clue</button></div>`,()=>{$('#savePinModal').onclick=async()=>{await post(`/api/admin/mysteries/${mid}/pins`,{label:$('#fPinLabel').value,page_slug:$('#fPinPage').value||null,note:$('#fPinNote').value,visibility:'players',x:.2+Math.random()*.6,y:.2+Math.random()*.6});closeModal();await load();toast('Clue pinned')}})}
function mysteryPinOptions(m,selected=''){return (m?.pins||[]).map(p=>`<option value="${p.id}" ${String(p.id)===String(selected)?'selected':''}>${esc(p.label)}</option>`).join('')}
function connectionsModal(m){if(!m)return;modal(`<div class="campaign-modal-wide mystery-connection-editor"><span class="eyebrow">INVESTIGATION BOARD</span><h2>${esc(m.title)} · connections</h2><p class="storage-help">Connect clues with red-string relationships. Player-visible connections appear behind the clue cards on the party mystery board; GM-only strings stay private.</p><div class="mystery-edge-create"><label>From<select id="fEdgeSource">${mysteryPinOptions(m)}</select></label><span>⌁</span><label>To<select id="fEdgeTarget">${mysteryPinOptions(m,m.pins?.[1]?.id||'')}</select></label><label>Label<input id="fEdgeLabel" placeholder="same symbol / alibi contradicts / leads to"></label><label>Visibility<select id="fEdgeVis"><option value="players">Players</option><option value="gm">GM only</option></select></label><button id="fEdgeAdd" class="compile-btn">Connect clues</button></div><div class="mystery-edge-list" id="mysteryEdgeList"></div><div class="mystery-clue-list"><div class="cc-section-subhead"><div><small>CLUES ON THIS BOARD</small><h3>Manage clue cards</h3></div></div>${(m.pins||[]).map(p=>`<div class="mystery-clue-manage"><div><strong>${esc(p.label)}</strong><small>${esc(p.note||'No note')}</small></div><button class="danger-text" data-delete-pin="${p.id}">Delete clue</button></div>`).join('')}</div><div class="modal-actions"><button class="quiet-btn" data-close-modal>Done</button></div></div>`,()=>{const renderEdges=()=>{$('#mysteryEdgeList').innerHTML=(m.edges||[]).map(e=>`<div class="mystery-edge-row"><span>⌁</span><div><strong>${esc(e.source_label||m.pins.find(p=>p.id===e.source_pin)?.label||'Clue')} → ${esc(e.target_label||m.pins.find(p=>p.id===e.target_pin)?.label||'Clue')}</strong><small>${esc(e.label||'Unlabelled connection')} · ${e.visibility==='gm'?'GM only':'players'}</small></div><button data-edit-edge="${e.id}">Edit</button><button class="danger-text" data-delete-edge="${e.id}">×</button></div>`).join('')||'<div class="empty-mini">No strings yet. Choose two clues above to connect them.</div>';$$('[data-edit-edge]').forEach(b=>b.onclick=()=>edgeEditModal(m,m.edges.find(e=>e.id===+b.dataset.editEdge)));$$('[data-delete-edge]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this connection?'))return;await del('/api/admin/mystery-edges/'+b.dataset.deleteEdge);await load();m=D.mysteries.find(x=>x.id===m.id);renderEdges();toast('Connection removed')})};renderEdges();$('[data-close-modal]').onclick=closeModal;$('#fEdgeAdd').onclick=async()=>{const source=+$('#fEdgeSource').value,target=+$('#fEdgeTarget').value;if(source===target)return toast('Choose two different clues','error');await post(`/api/admin/mysteries/${m.id}/edges`,{source_pin:source,target_pin:target,label:$('#fEdgeLabel').value,visibility:$('#fEdgeVis').value});await load();m=D.mysteries.find(x=>x.id===m.id);$('#fEdgeLabel').value='';renderEdges();toast('Clues connected')};$$('[data-delete-pin]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this clue and all strings attached to it?'))return;await del('/api/admin/mystery-pins/'+b.dataset.deletePin);closeModal();await load();connectionsModal(D.mysteries.find(x=>x.id===m.id));toast('Clue deleted')})})}
function edgeEditModal(m,e){if(!m||!e)return;modal(`<h2>Edit connection</h2><label>From<select id="fEdgeEditSource">${mysteryPinOptions(m,e.source_pin)}</select></label><label>To<select id="fEdgeEditTarget">${mysteryPinOptions(m,e.target_pin)}</select></label><label>Label<input id="fEdgeEditLabel" value="${esc(e.label||'')}"></label><label>Visibility<select id="fEdgeEditVis"><option value="players">Players</option><option value="gm" ${e.visibility==='gm'?'selected':''}>GM only</option></select></label><div class="modal-actions"><button id="fEdgeEditSave" class="compile-btn">Save connection</button></div>`,()=>{$('#fEdgeEditSave').onclick=async()=>{const source=+$('#fEdgeEditSource').value,target=+$('#fEdgeEditTarget').value;if(source===target)return toast('Choose two different clues','error');await post(`/api/admin/mysteries/${m.id}/edges`,{...e,source_pin:source,target_pin:target,label:$('#fEdgeEditLabel').value,visibility:$('#fEdgeEditVis').value});closeModal();await load();connectionsModal(D.mysteries.find(x=>x.id===m.id));toast('Connection updated')}})}
$('#ccNewMystery').onclick=()=>mysteryModal({status:'open',visibility:'players'});
function renderHandouts(){$('#ccHandoutList').innerHTML=(D.handouts||[]).map(h=>`<article class="cc-item-card handout"><span>✉</span><small>${esc(h.kind).toUpperCase()}${h.expires_at?' · TEMPORARY':''}</small><h2>${esc(h.title)}</h2><p>${esc((h.body||'').replace(/<[^>]+>/g,' ').slice(0,150))}</p><div><button data-edit-handout="${h.id}">Edit</button><a href="/handout/${esc(h.slug)}">Open ↗</a><button data-del-handout="${h.id}" class="danger-text">Delete</button></div></article>`).join('')||'<div class="empty-mini">No handouts yet.</div>';$$('[data-edit-handout]').forEach(b=>b.onclick=()=>handoutModal(D.handouts.find(x=>x.id===+b.dataset.editHandout)));$$('[data-del-handout]').forEach(b=>b.onclick=async()=>{if(confirm('Delete handout?')){await del('/api/admin/handouts/'+b.dataset.delHandout);await load()}})}
function handoutModal(h={}){const exp=h.expires_at?new Date(h.expires_at*1000).toISOString().slice(0,16):'';modal(`<h2>${h.id?'Edit':'New'} handout</h2><label>Title<input id="fHandTitle" value="${esc(h.title||'')}"></label><label>Style<select id="fHandKind">${['parchment','letter','contract','newspaper','wanted','journal','vision','sketch'].map(k=>`<option value="${k}" ${h.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Content <small>HTML is allowed for intentional layout.</small><textarea id="fHandBody" rows="12">${esc(h.body||'')}</textarea></label><label>Related lore<select id="fHandPage">${pageOptions(h.page_slug||'')}</select></label><label>Session<select id="fHandSession"><option value="">Any time</option>${(D.sessions||[]).map(s=>`<option value="${s.id}" ${+h.session_id===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>Temporary expiry<input id="fHandExpires" type="datetime-local" value="${exp}"></label><label>Visibility<select id="fHandVis"><option value="players">Players</option><option value="gm" ${h.visibility==='gm'?'selected':''}>GM only</option></select></label><div class="modal-actions"><button id="saveHandModal" class="compile-btn">Save handout</button></div>`,()=>{$('#saveHandModal').onclick=async()=>{const dt=$('#fHandExpires').value;await post('/api/admin/handouts',{...h,title:$('#fHandTitle').value,kind:$('#fHandKind').value,body:$('#fHandBody').value,page_slug:$('#fHandPage').value||null,session_id:+$('#fHandSession').value||null,expires_at:dt?new Date(dt).getTime()/1000:null,visibility:$('#fHandVis').value});closeModal();await load();toast('Handout saved')}})}$('#ccNewHandout').onclick=()=>handoutModal({kind:'parchment',visibility:'players'});
let worldDraft={months:[],weekdays:[],moons:[]};
function renderWorld(){const c=D.calendar||{};worldDraft={months:(c.months||[]).map(x=>({...x})),weekdays:(c.weekdays||[]).map(x=>typeof x==='string'?x:(x.name||'')),moons:(c.moons||[]).map(x=>({...x}))};$('#ccCalendarName').value=c.name||'Campaign Calendar';$('#ccCampaignDate').value=c.current_date||'';$('#ccCampaignSeason').value=c.season||'';$('#ccWorldWidth').value=c.world_width||1000;$('#ccTravelSpeed').value=c.travel_speed||40;renderWorldRows();const prog=$('#ccWorldProgress');if(prog){const stats=[['Months',worldDraft.months.length],['Historical eras',(D.timeline_eras||[]).length],['Historical events',(D.timeline||[]).filter(x=>!['session','festival'].includes(x.kind)).length],['Relationships',(D.relationships||[]).length],['Maps',(D.maps||maps).length]];prog.innerHTML=stats.map(([a,b])=>`<div><strong>${esc(b)}</strong><span>${esc(a)}</span></div>`).join('')}}
function renderWorldRows(){const mh=$('#ccMonthRows'),wh=$('#ccWeekdayRows'),moonh=$('#ccMoonRows');if(mh){mh.innerHTML=worldDraft.months.map((m,i)=>`<div class="structured-row month-row"><span class="drag-handle">⋮⋮</span><label>Name<input data-month-name="${i}" value="${esc(m.name||'')}"></label><label>Days<input data-month-days="${i}" type="number" min="1" value="${esc(m.days||'')}"></label><label>Season<input data-month-season="${i}" value="${esc(m.season||'')}"></label><button data-remove-month="${i}">×</button></div>`).join('')||'<div class="empty-mini">No months yet. Add the first one.</div>';$$('[data-remove-month]').forEach(b=>b.onclick=()=>{worldDraft.months.splice(+b.dataset.removeMonth,1);renderWorldRows()});$$('[data-month-name]').forEach(x=>x.oninput=()=>worldDraft.months[+x.dataset.monthName].name=x.value);$$('[data-month-days]').forEach(x=>x.oninput=()=>worldDraft.months[+x.dataset.monthDays].days=+x.value||null);$$('[data-month-season]').forEach(x=>x.oninput=()=>worldDraft.months[+x.dataset.monthSeason].season=x.value)}if(wh){wh.innerHTML=worldDraft.weekdays.map((d,i)=>`<label class="weekday-edit-chip"><input data-weekday="${i}" value="${esc(d)}"><button data-remove-weekday="${i}" type="button">×</button></label>`).join('')||'<div class="empty-mini">No weekdays yet.</div>';$$('[data-remove-weekday]').forEach(b=>b.onclick=()=>{worldDraft.weekdays.splice(+b.dataset.removeWeekday,1);renderWorldRows()});$$('[data-weekday]').forEach(x=>x.oninput=()=>worldDraft.weekdays[+x.dataset.weekday]=x.value)}if(moonh){moonh.innerHTML=worldDraft.moons.map((m,i)=>`<div class="structured-row moon-row"><span class="moon-glyph">☾</span><label>Name<input data-moon-name="${i}" value="${esc(m.name||'')}"></label><label>Cycle days<input data-moon-cycle="${i}" type="number" min="1" step=".1" value="${esc(m.cycle||'')}"></label><label>Meaning / note<input data-moon-note="${i}" value="${esc(m.note||'')}"></label><button data-remove-moon="${i}">×</button></div>`).join('')||'<div class="empty-mini">No celestial cycles yet.</div>';$$('[data-remove-moon]').forEach(b=>b.onclick=()=>{worldDraft.moons.splice(+b.dataset.removeMoon,1);renderWorldRows()});$$('[data-moon-name]').forEach(x=>x.oninput=()=>worldDraft.moons[+x.dataset.moonName].name=x.value);$$('[data-moon-cycle]').forEach(x=>x.oninput=()=>worldDraft.moons[+x.dataset.moonCycle].cycle=+x.value||null);$$('[data-moon-note]').forEach(x=>x.oninput=()=>worldDraft.moons[+x.dataset.moonNote].note=x.value)}}
async function saveWorld(){const payload={calendar_name:$('#ccCalendarName').value,campaign_date:$('#ccCampaignDate').value,campaign_season:$('#ccCampaignSeason').value,calendar_months:worldDraft.months.filter(x=>x.name),calendar_weekdays:worldDraft.weekdays.filter(Boolean),calendar_moons:worldDraft.moons.filter(x=>x.name),world_width:+$('#ccWorldWidth').value||1000,travel_speed:+$('#ccTravelSpeed').value||40};const out=await put('/api/admin/world-settings',payload);D.calendar=out.calendar||payload;toast('World settings saved');renderDashboard();renderWorld()}$('#ccSaveWorld').onclick=saveWorld;$('#ccSaveQuickDate').onclick=async()=>{$('#ccCampaignDate').value=$('#ccQuickDate').value;await saveWorld()};$('#ccAddMonth').onclick=()=>{worldDraft.months.push({name:'New month',days:30,season:''});renderWorldRows()};$('#ccAddWeekday').onclick=()=>{worldDraft.weekdays.push('New day');renderWorldRows()};$('#ccAddMoon').onclick=()=>{worldDraft.moons.push({name:'New moon',cycle:28,note:''});renderWorldRows()};$$('[data-world-panel]').forEach(b=>b.onclick=()=>{$$('[data-world-panel]').forEach(x=>x.classList.toggle('active',x===b));$$('.world-builder-panel').forEach(x=>x.classList.toggle('active',x.id==='world-panel-'+b.dataset.worldPanel))});$$('[data-world-jump]').forEach(b=>b.onclick=()=>tab(b.dataset.worldJump));$$('[data-template-kind]').forEach(b=>b.onclick=()=>{$$('[data-template-kind]').forEach(x=>x.classList.toggle('active',x===b));$('#ccTemplateKind').value=b.dataset.templateKind;$('#ccTemplateTitle').focus()});$$('[data-template-kind="person"]')[0]?.classList.add('active');
$('#ccGenerateTemplate').onclick=async()=>{const d=await post('/api/admin/entry-template',{kind:$('#ccTemplateKind').value,title:$('#ccTemplateTitle').value||'New Entry'});$('#ccTemplatePreview').textContent=d.content;try{await navigator.clipboard.writeText(d.content);toast('LaTeX scaffold generated and copied')}catch(_){toast('LaTeX scaffold generated')}};$('#ccCreateTemplateFile').onclick=async()=>{const title=$('#ccTemplateTitle').value.trim();if(!title)return toast('Give the entry a title first','error');try{const d=await post('/api/admin/entry-template/create',{kind:$('#ccTemplateKind').value,title});toast('Entry created · opening Seeker Studio');location.href=d.edit_url}catch(e){toast(e.message,'error')}};$('#ccCreateEntry').onclick=()=>{tab('world');setTimeout(()=>{$('[data-world-panel="create"]')?.click();$('#ccTemplateTitle').focus()},80)};


function renderAtlas(){
  const host=$('#ccAtlasList');if(!host)return;const rows=D.maps||maps;
  host.innerHTML=rows.length?rows.map(m=>`<article class="cc-atlas-card"><div class="cc-atlas-thumb" style="background-image:url('/uploads/${esc(m.image_path)}')"></div><div class="cc-atlas-content"><header><div><small>${m.markers?.length||0} MARKERS · ${m.layers?.length||0} LAYERS · ${m.fog_regions?.filter(f=>!f.revealed).length||0} HIDDEN REGIONS</small><h2>${esc(m.name)}</h2></div><div class="cc-atlas-actions"><a class="quiet-btn" href="/atlas/${esc(m.slug)}">Player ↗</a><button class="quiet-btn" data-add-layer="${m.id}">＋ Layer</button><button class="quiet-btn" data-add-fog="${m.id}">＋ Discovery fog</button></div></header><div class="cc-atlas-group"><small>LAYERS</small>${(m.layers||[]).map(l=>`<div class="cc-layer-row"><span>◫</span><div><strong>${esc(l.name)}</strong><small>${esc(l.kind)} · ${Math.round((l.opacity||0)*100)}% · ${l.visible_to_players?'players':'GM only'}</small></div><button data-edit-layer="${l.id}" data-map="${m.id}">Edit</button><button class="danger-text" data-del-layer="${l.id}">×</button></div>`).join('')||'<div class="empty-mini">No overlays yet.</div>'}</div><div class="cc-atlas-group"><small>DISCOVERY FOG</small>${(m.fog_regions||[]).map(f=>`<div class="cc-layer-row"><span>${f.revealed?'○':'◉'}</span><div><strong>${esc(f.title)}</strong><small>${esc(f.style)} · ${f.points?.length||0} points · ${f.revealed?'revealed':'hidden from players'}</small></div><button data-edit-fog="${f.id}" data-map="${m.id}">Draw/Edit</button><button data-toggle-fog="${f.id}" data-map="${m.id}">${f.revealed?'Hide':'Reveal'}</button><button class="danger-text" data-del-fog="${f.id}">×</button></div>`).join('')||'<div class="empty-mini">No undiscovered regions drawn.</div>'}</div></div></article>`).join(''):'<div class="timeline-empty"><h2>No maps yet.</h2><p>Create a map in Seeker Studio → Maps first.</p></div>';
  $$('[data-add-layer]').forEach(b=>b.onclick=()=>layerUploadModal(rows.find(m=>m.id===+b.dataset.addLayer)));
  $$('[data-edit-layer]').forEach(b=>b.onclick=()=>{const m=rows.find(x=>x.id===+b.dataset.map),l=m?.layers?.find(x=>x.id===+b.dataset.editLayer);if(l)layerEditModal(m,l)});
  $$('[data-del-layer]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this map layer?')){await del('/api/admin/map-layers/'+b.dataset.delLayer);await load();toast('Layer deleted')}});
  $$('[data-add-fog]').forEach(b=>b.onclick=()=>fogDrawModal(rows.find(m=>m.id===+b.dataset.addFog),{}));
  $$('[data-edit-fog]').forEach(b=>b.onclick=()=>{const m=rows.find(x=>x.id===+b.dataset.map),f=m?.fog_regions?.find(x=>x.id===+b.dataset.editFog);if(f)fogDrawModal(m,f)});
  $$('[data-toggle-fog]').forEach(b=>b.onclick=async()=>{const m=rows.find(x=>x.id===+b.dataset.map),f=m?.fog_regions?.find(x=>x.id===+b.dataset.toggleFog);if(!f)return;await post(`/api/admin/maps/${m.id}/fog`,{...f,revealed:!f.revealed});await load();toast(f.revealed?'Region hidden again':'Region revealed to players')});
  $$('[data-del-fog]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this discovery-fog region?')){await del('/api/admin/map-fog/'+b.dataset.delFog);await load();toast('Fog region deleted')}})
}
function layerUploadModal(m){if(!m)return;modal(`<h2>Add map layer · ${esc(m.name)}</h2><label>Name<input id="fLayerName" value="Political borders"></label><label>Layer image<input id="fLayerFile" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="form-grid"><label>Kind<select id="fLayerKind">${['political','roads','trade','religion','climate','ruins','military','overlay'].map(k=>`<option value="${k}">${k}</option>`).join('')}</select></label><label>Opacity<input id="fLayerOpacity" type="range" min="0" max="1" step="0.05" value="0.7"></label></div><label class="check-row"><input id="fLayerPlayers" type="checkbox" checked> Visible to players</label><p class="storage-help">For best alignment, export the overlay at exactly the same pixel dimensions as the base map with transparent areas where nothing changes.</p><div class="modal-actions"><button id="saveLayerUpload" class="compile-btn">Upload layer</button></div>`,()=>{$('#saveLayerUpload').onclick=async()=>{const file=$('#fLayerFile').files?.[0];if(!file)return toast('Choose a layer image','error');const fd=new FormData();fd.append('name',$('#fLayerName').value||'Map layer');fd.append('kind',$('#fLayerKind').value);fd.append('opacity',$('#fLayerOpacity').value);fd.append('visible_to_players',$('#fLayerPlayers').checked?'true':'false');fd.append('image',file);await api(`/api/admin/maps/${m.id}/layers/upload`,{method:'POST',body:fd});closeModal();await load();toast('Map layer uploaded')}})}
function layerEditModal(m,l){modal(`<h2>Edit layer</h2><label>Name<input id="fLayerEditName" value="${esc(l.name)}"></label><div class="form-grid"><label>Kind<select id="fLayerEditKind">${['political','roads','trade','religion','climate','ruins','military','overlay'].map(k=>`<option value="${k}" ${l.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Opacity<input id="fLayerEditOpacity" type="range" min="0" max="1" step="0.05" value="${l.opacity??.7}"></label></div><label class="check-row"><input id="fLayerEditPlayers" type="checkbox" ${l.visible_to_players?'checked':''}> Visible to players</label><label class="check-row"><input id="fLayerEditEnabled" type="checkbox" ${l.enabled!==0?'checked':''}> Enabled</label><div class="modal-actions"><button id="saveLayerEdit" class="compile-btn">Save layer</button></div>`,()=>{$('#saveLayerEdit').onclick=async()=>{await post(`/api/admin/maps/${m.id}/layers`,{...l,name:$('#fLayerEditName').value,kind:$('#fLayerEditKind').value,opacity:+$('#fLayerEditOpacity').value,visible_to_players:$('#fLayerEditPlayers').checked,enabled:$('#fLayerEditEnabled').checked});closeModal();await load();toast('Layer updated')}})}
function fogDrawModal(m,f={}){if(!m)return;const points=(f.points||[]).map(p=>[+p[0],+p[1]]);modal(`<div class="campaign-modal-wide"><h2>${f.id?'Edit':'Draw'} discovery fog · ${esc(m.name)}</h2><p class="storage-help">Click around the boundary of the undiscovered region. Seeker closes the polygon automatically. Use a few broad points for organic parchment/cloud cover.</p><div class="fog-draw-stage" id="fogDrawStage"><img src="/uploads/${esc(m.image_path)}" alt=""><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polygon id="fogPreviewPoly"></polygon><g id="fogPreviewPoints"></g></svg></div><div class="fog-draw-tools"><button id="fogUndo">Undo point</button><button id="fogReset">Reset</button><span id="fogPointCount"></span></div><div class="form-grid"><label>Region name<input id="fFogTitle" value="${esc(f.title||'Unknown region')}"></label><label>Style<select id="fFogStyle"><option value="parchment">Parchment</option><option value="cloud" ${f.style==='cloud'?'selected':''}>Clouds</option><option value="void" ${f.style==='void'?'selected':''}>Dark unknown</option></select></label></div><label class="check-row"><input id="fFogRevealed" type="checkbox" ${f.revealed?'checked':''}> Already revealed to players</label><div class="modal-actions"><button id="saveFog" class="compile-btn">Save region</button></div></div>`,()=>{const stage=$('#fogDrawStage'),poly=$('#fogPreviewPoly'),dots=$('#fogPreviewPoints'),count=$('#fogPointCount');const draw=()=>{poly.setAttribute('points',points.map(p=>`${p[0]*100},${p[1]*100}`).join(' '));dots.innerHTML=points.map(p=>`<circle cx="${p[0]*100}" cy="${p[1]*100}" r="0.8"></circle>`).join('');count.textContent=points.length+' points'};draw();stage.onclick=e=>{const r=stage.getBoundingClientRect();points.push([(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]);draw()};$('#fogUndo').onclick=()=>{points.pop();draw()};$('#fogReset').onclick=()=>{points.splice(0);draw()};$('#saveFog').onclick=async()=>{if(points.length<3)return toast('Draw at least three points','error');await post(`/api/admin/maps/${m.id}/fog`,{...f,title:$('#fFogTitle').value||'Unknown region',style:$('#fFogStyle').value,revealed:$('#fFogRevealed').checked,points});closeModal();await load();toast('Discovery fog saved')}})}

function renderHealth(){const h=D.health||{counts:{},issues:[]};$('#ccHealthStats').innerHTML=Object.entries(h.counts||{}).map(([k,v])=>`<div class="cc-stat"><strong>${esc(v)}</strong><span>${esc(k.replaceAll('_',' '))}</span></div>`).join('');$('#ccHealthIssues').innerHTML=(h.issues||[]).map(i=>`<a class="cc-list-row health ${esc(i.severity)}" href="${esc(i.href||'#')}"><span>${i.severity==='warning'?'⚠':'·'}</span><div><strong>${esc(i.title)}</strong><p>${esc(i.message)}</p></div><i>→</i></a>`).join('')||'<div class="health-clean"><span>✓</span><strong>No structural problems found.</strong></div>'}$('#ccRefreshHealth').onclick=async()=>{D.health=await api('/api/admin/health-report');renderHealth();renderDashboard();toast('Lore health scan complete')};
function renderSnapshots(){$('#ccSnapshotList').innerHTML=(D.snapshots||[]).map(s=>`<div class="cc-list-row"><span>◫</span><div><strong>${esc(s.label)}</strong><small>${new Date(s.created_at*1000).toLocaleString()}</small></div><a href="/api/admin/snapshots/${s.id}/download">Download</a><button data-restore-snapshot="${s.id}">Restore</button></div>`).join('')||'<div class="empty-mini">No campaign snapshots yet.</div>';$$('[data-restore-snapshot]').forEach(b=>b.onclick=async()=>{const s=(D.snapshots||[]).find(x=>x.id===+b.dataset.restoreSnapshot);if(!confirm(`Restore “${s?.label||'snapshot'}”? Seeker will first create an automatic backup of the current state.`))return;toast('Restoring snapshot…');await post('/api/admin/snapshots/'+b.dataset.restoreSnapshot+'/restore',{});location.reload()})}$('#ccNewSnapshot').onclick=()=>modal(`<h2>Create campaign snapshot</h2><label>Label<input id="fSnapshotLabel" value="Before Session ${(D.sessions||[]).length+1}"></label><p class="storage-help">Snapshots include source, uploads, and a transactionally consistent Seeker database.</p><div class="modal-actions"><button id="saveSnapshotModal" class="compile-btn">Create snapshot</button></div>`,()=>{$('#saveSnapshotModal').onclick=async()=>{await post('/api/admin/snapshots',{label:$('#fSnapshotLabel').value});closeModal();await load();toast('Campaign snapshot created')}});
load().catch(e=>{console.error(e);toast(e.message,'error')});
})();
